    fn get_messages_around(&self, message_id: i64, before: i64, after: i64) -> DbResult<Option<(String, Vec<ConversationMessage>)>>;

    /// Logic: 3-phase: AND-first FTS5 → OR fallback → LIKE fallback
    /// Table: conversation_messages
    fn search_conversation_messages(&self, query: &str, limit: i64) -> DbResult<Vec<ConversationMessage>>;

    /// Logic: dynamic WHERE with SQL-pushed filters + 3-phase FTS
    /// Table: conversation_messages
    fn search_messages_filtered(&self, query: &str, session_id: Option<&str>, role: Option<&str>, tool_name: Option<&str>, time_after: Option<&str>, limit: i64) -> DbResult<Vec<ConversationMessage>>;

    /// Logic: grouped BM25 scoring with AND→OR→LIKE fallback
    /// Table: conversation_messages
    fn search_conversation_sessions_fts(&self, query: &str, limit: i64) -> DbResult<Vec<(String, f64)>>;

    /// Logic: FTS5 snippet() extraction with ranking
    /// Table: conversation_messages
    fn get_session_fts_snippets(&self, session_id: &str, query: &str, limit: usize) -> DbResult<Vec<(String, String)>>;

    /// Logic: FTS5 session search with time/project filters
    /// Table: conversation_messages
    fn search_conversation_sessions_fts_filtered(&self, query: &str, limit: i64, time_after: Option<&str>, project: Option<&str>) -> DbResult<Vec<(String, f64)>>;

